import * as THREE from "three";
import build from "../../samples/phoenix";

const root = build();
const box = new THREE.Box3().setFromObject(root, true);
const size = box.getSize(new THREE.Vector3());
let parts = 0;
let tris = 0;
let joints = 0;
root.traverse((o) => {
  if ((o as THREE.Mesh).isMesh) {
    parts++;
    const g = (o as THREE.Mesh).geometry;
    tris += (g.index ? g.index.count : g.attributes.position.count) / 3;
  }
  if ((o as THREE.Bone).isBone || o.type === "Group" || o.type === "Object3D") joints++;
});
const colors = new Set<string>();
root.traverse((o) => {
  const m = (o as THREE.Mesh).material as THREE.MeshStandardMaterial | undefined;
  if (m && m.name !== "paint" && !m.map) colors.add(m.color.getHexString());
});
console.log({ parts, tris, joints, flat: colors.size, min: box.min.toArray().map((x) => +x.toFixed(3)), max: box.max.toArray().map((x) => +x.toFixed(3)), size: size.toArray().map((x) => +x.toFixed(2)) });
console.log(JSON.stringify((root.userData.rig?.chains ?? []).length));
